        children: "@Provider\npublic class PersistenceExceptionMapper\n    implements ExceptionMapper<PersistenceException> {\n\n    @Override\n    public Response toResponse(PersistenceException exception) {\n        PersistenceErrorKind kind =\n            PostgresErrorClassifier.classify(exception);\n\n        return switch (kind) {\n            case UNIQUE_VIOLATION -> conflict(\"DUPLICATE_RESOURCE\");\n            case FOREIGN_KEY_VIOLATION -> conflict(\"INVALID_REFERENCE\");\n            case CHECK_VIOLATION -> conflict(\"CONSTRAINT_VIOLATION\");\n            case DEADLOCK, SERIALIZATION_FAILURE, CONNECTION_FAILURE ->\n                unavailable(\"PERSISTENCE_TRANSIENT_FAILURE\");\n            case LOCK_NOT_AVAILABLE, QUERY_CANCELED ->\n                unavailable(\"PERSISTENCE_TIMEOUT_OR_BUSY\");\n            default -> serverError(\"PERSISTENCE_FAILURE\");\n        };\n    }\n\n    private Response conflict(String code) {\n        return Response.status(Response.Status.CONFLICT)\n            .entity(ApiError.of(code, \"Request conflicts with current state.\"))\n            .build();\n    }\n\n    private Response unavailable(String code) {\n        return Response.status(Response.Status.SERVICE_UNAVAILABLE)\n            .entity(ApiError.of(code, \"Temporary persistence failure. Retry later.\"))\n            .build();\n    }\n\n    private Response serverError(String code) {\n        return Response.status(Response.Status.INTERNAL_SERVER_ERROR)\n            .entity(ApiError.of(code, \"Unexpected persistence failure.\"))\n            .build();\n    }\n}\n"
